namespace Bingo.Domain.Boards;

public sealed class BoardRequirementDropSnapshot { private BoardRequirementDropSnapshot() { } public BoardRequirementDropSnapshot(Guid id, Guid requirementId, Guid sourceDropId, Guid itemIdSnapshot, string boss, string item, string displayRate, decimal? probability, int? maximum, decimal? ehb, int creditedWeight = 1) { ArgumentOutOfRangeException.ThrowIfLessThan(creditedWeight, 1); Id = id; RequirementId = requirementId; SourceDropId = sourceDropId; ItemIdSnapshot = itemIdSnapshot; BossName = boss; ItemName = item; DisplayRate = displayRate; NumericProbability = probability; MaximumContribution = maximum; EhbPerContribution = ehb; CreditedWeight = creditedWeight; } public Guid Id { get; private set; } public Guid RequirementId { get; private set; } public Guid SourceDropId { get; private set; } public Guid ItemIdSnapshot { get; private set; } public string BossName { get; private set; } = string.Empty; public string ItemName { get; private set; } = string.Empty; public string DisplayRate { get; private set; } = string.Empty; public decimal? NumericProbability { get; private set; } public int? MaximumContribution { get; private set; } public decimal? EhbPerContribution { get; private set; } public int CreditedWeight { get; private set; } = 1; }
